import 'server-only';

/**
 * Brincadeira da bancada com o Gê: o login dele "pede autenticação de dois
 * fatores" — a aprovação do pai e da namorada (piada interna). Não existe 2FA nenhum no
 * site; a senha certa entra, a sessão é desfeita na hora e a tela mostra o
 * aviso com a foto. Senha errada leva a mensagem de sempre.
 *
 * Para acabar com a brincadeira: tire o usuário de `USUARIOS_TRAVADOS` (ou
 * apague este arquivo e as duas referências em `entrar`, em
 * src/app/painel/actions.ts).
 *
 * A foto vai embutida aqui, e não em `public/`: lá ela ficaria aberta para
 * qualquer um em varzometro.com.br/cestinha.jpeg. Assim as fotos só chegam ao
 * navegador na resposta do login do Gê.
 */
export const USUARIOS_TRAVADOS = ['ge'];

export const AVISO_DOIS_FATORES =
  'Esta conta precisa de autenticação de dois fatores para entrar. A aprovação foi enviada para os responsáveis cadastrados.';

export type Responsavel = { quem: string; foto: string };

export const RESPONSAVEIS: Responsavel[] = [
  { quem: 'Pai', foto: 'data:image/jpeg;base64,' },
  { quem: 'Namorada', foto: 'data:image/jpeg;base64,' },
];
